    fun `reference`(): IdentityReference

    suspend fun `snapshot`(): IdentitySnapshot

    suspend fun `updateMetadata`(`expected`: IdentityMetadataGuard, `metadata`: IdentityMetadata): IdentityMetadataGuard

    companion object
}

