sealed class IdentityCommand {

    data class Create(
        val v1: uniffi.prns_identities.IdentityCreateRequest) : IdentityCommand()

    {


        companion object
    }

    data class Transition(
        val v1: uniffi.prns_identities.IdentityPreparedTransition) : IdentityCommand()

    {


        companion object
    }








    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeIdentityCommand : FfiConverterRustBuffer<IdentityCommand>{
    override fun read(buf: ByteBuffer): IdentityCommand {
        return when(buf.getInt()) {
            1 -> IdentityCommand.Create(
                FfiConverterTypeIdentityCreateRequest.read(buf),
                )
            2 -> IdentityCommand.Transition(
                FfiConverterTypeIdentityPreparedTransition.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: IdentityCommand) = when(value) {
        is IdentityCommand.Create -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeIdentityCreateRequest.allocationSize(value.v1)
            )
        }
        is IdentityCommand.Transition -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeIdentityPreparedTransition.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: IdentityCommand, buf: ByteBuffer) {
        when(value) {
            is IdentityCommand.Create -> {
                buf.putInt(1)
                FfiConverterTypeIdentityCreateRequest.write(value.v1, buf)
                Unit
            }
            is IdentityCommand.Transition -> {
                buf.putInt(2)
                FfiConverterTypeIdentityPreparedTransition.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






